 for p,os in oss.items():
  arr=[]
  for d,tag in os:
   h=max(r for r,c in d)+1;w=max(c for r,c in d)+1
   if p==marked_piece:
    if not any(v==5 and (r,c)==(0,0) for (r,c),v in d.items()): continue
    offsets=[(0,0)]
   else: offsets=[(r,c) for r in range(N-h+1) for c in range(N-w+1)]
   for r0,c0 in offsets:
    if r0+h>N or c0+w>N: continue
    b=0
    for r,c in d: b|=1<<((r+r0)*N+(c+c0))
    arr.append((b,d,tag,r0,c0))
  pls[p]=arr
  by[p]=[[] for _ in range(N*N)]
  for i,pl in enumerate(arr):
   b=pl[0]
   while b:
    low=b&-b; j=low.bit_length()-1;by[p][j].append(i);b-=low
 marks=pls[marked_piece]
 for m in marks:
  if len(m[1])>N*N: continue
  chosen=[]
  def rec(occ,rem,chosen):
   if not rem:return occ==full
   un=full^occ; best=None
   while un:
    lo=un&-un;j=lo.bit_length()-1;un-=lo
    opts=[]
    for p in rem:
