    if not opts:return False
    if best is None or len(opts)<len(best):best=opts
    if len(best)==1:break
   for p,pl in best:
    if rec(occ|pl[0],tuple(q for q in rem if q!=p),chosen+[(p,pl)]):return True
   return False
  if rec(m[0],tuple(remaining),[(marked_piece,m)]):return chosen
 return None
